-- Create "outbox_messages" table
CREATE TABLE "outbox_messages" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "topic" character varying NOT NULL, "payload" jsonb NOT NULL, "created_at" timestamptz NOT NULL, "available_at" timestamptz NOT NULL, "sent_at" timestamptz NULL, "attempts" bigint NOT NULL DEFAULT 0, "last_error" text NULL, PRIMARY KEY ("id"));
-- Create index "outboxmessage_available_at_id" to table: "outbox_messages"
CREATE INDEX "outboxmessage_available_at_id" ON "outbox_messages" ("available_at", "id") WHERE (sent_at IS NULL);
